import 'leaflet/dist/leaflet.css'; // Importar CSS de Leaflet
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import UserForm from './pages/UserForm';
import Home from './pages/home';
import MisDatosPage from './pages/MisDatosPage';
import Header from './components/header';
import ReportarMascotaPage from './pages/ReportarMascotaPage';
import MascotasReportadasPage from './pages/MascotasReportadasPage';
import ModificarDatosPage from './pages/ModificarDatosPage';
import Search from './pages/Search';
import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from './context/AuthContext'; // Asegúrate de que la ruta sea correcta

function App() {
  const [mascotas, setMascotas] = useState([]);
  const { user } = useContext(AuthContext); // Obtener el usuario logueado

const fetchMascotas = async () => {
  if (!user) return;
  try {
    const response = await fetch(`http://localhost:3000/api/pets?reporterId=${user.id}`);
    const data = await response.json();
    console.log(data); // Agrega esto para verificar la respuesta
    setMascotas(data);
  } catch (error) {
    console.error('Error al obtener las mascotas:', error);
  }
};

  useEffect(() => {
    fetchMascotas();
  }, [user]);

  return (
    <Router>
      <Header />
      <Routes>
        <Route path="/" element={<UserForm />} />
        <Route path="/home" element={<Home />} />
        <Route path="/mis-datos" element={<MisDatosPage />} />
        <Route path="/mascotas-reportadas" element={<MascotasReportadasPage mascotas={mascotas} />} />
        <Route path="/reportar-mascota" element={<ReportarMascotaPage fetchMascotas={fetchMascotas} user={user} />} />
        <Route path="/modificar-datos" element={<ModificarDatosPage />} />
        <Route path="/buscar" element={<Search />} />
      </Routes>
    </Router>
  );
}

export default App;
